<script setup>
import {computed,ref,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {useMarketStore} from '../stores/market'
import {CATEGORIES,COLLEGES} from '../data/seed'
import ProductCard from '../components/ProductCard.vue'
import Icon from '../components/Icon.vue'
const route=useRoute(),router=useRouter(),market=useMarketStore()
const q=ref(String(route.query.q||'')),category=ref(String(route.query.category||'all')),college=ref(''),condition=ref(''),price=ref(''),sort=ref('new'),page=ref(1)
watch(()=>route.query,value=>{q.value=String(value.q||'');category.value=String(value.category||'all');page.value=1})
const filtered=computed(()=>market.products.filter(p=>p.status==='available'&&(category.value==='all'||p.category===category.value)&&(!q.value||`${p.title} ${p.description} ${p.sellerName}`.toLowerCase().includes(q.value.toLowerCase()))&&(!college.value||p.college===college.value)&&(!condition.value||p.condition===condition.value)&&(!price.value||({low:p.price<50,mid:p.price>=50&&p.price<=200,high:p.price>200})[price.value])).sort((a,b)=>sort.value==='price-up'?a.price-b.price:sort.value==='price-down'?b.price-a.price:new Date(b.createdAt)-new Date(a.createdAt)))
const pages=computed(()=>Math.ceil(filtered.value.length/12)),shown=computed(()=>filtered.value.slice((page.value-1)*12,page.value*12))
watch([q,category,college,condition,price,sort],()=>{page.value=1})
function reset(){q.value='';category.value='all';college.value='';condition.value='';price.value='';sort.value='new';router.replace('/market')}
</script>
<template><div class="page-width inner-page"><div class="breadcrumb"><RouterLink to="/">首页</RouterLink><Icon name="chevron" :size="13"/>校园市集</div><div class="market-intro"><div><span class="eyebrow">THE LIANXI FLEA MARKET</span><h1>闲置的美好，等一个刚好。</h1><p>在熟悉的校园里，发现下一份小小欢喜。</p></div><div class="market-intro-stamp"><Icon name="leaf" :size="30"/><span>旧物 · 新欢<br><small>GOOD FINDS AHEAD</small></span></div></div><form class="market-search" @submit.prevent><Icon name="search" :size="22"/><input v-model="q" placeholder="搜索书籍、数码、生活好物，或同学的名字…" aria-label="搜索商品"/><button class="button primary" type="submit">找找看<Icon name="arrow" :size="17"/></button></form><div class="market-layout"><aside class="filter-sidebar"><div class="sidebar-heading"><Icon name="filter" :size="17"/><h3>慢慢挑，刚刚好</h3><button @click="reset">重置</button></div><div class="filter-block"><label>好物分类</label><button v-for="item in [{id:'all',label:'全部闲置'},...CATEGORIES]" :key="item.id" :class="['category-filter',{active:category===item.id}]" @click="category=item.id"><Icon :name="({all:'grid',books:'book',digital:'digital',living:'living',fashion:'fashion',sports:'sports',tools:'tools'})[item.id]" :size="17"/>{{item.label}}<span>{{market.products.filter(p=>p.status==='available'&&(item.id==='all'||p.category===item.id)).length}}</span></button></div><div class="filter-block"><label for="college-filter">来自哪个学院</label><select id="college-filter" v-model="college"><option value="">全部学院</option><option v-for="item in COLLEGES" :key="item">{{item}}</option></select></div><div class="filter-block"><label>心仪的价格</label><label v-for="item in [{id:'',label:'不限价格'},{id:'low',label:'¥50 以下'},{id:'mid',label:'¥50 — ¥200'},{id:'high',label:'¥200 以上'}]" :key="item.id" class="radio-label"><input v-model="price" type="radio" :value="item.id"/>{{item.label}}</label></div><div class="filter-block"><label for="condition-filter">物品成色</label><select id="condition-filter" v-model="condition"><option value="">不限成色</option><option>全新</option><option>几乎全新</option><option>轻微使用</option><option>正常使用</option></select></div><div class="sidebar-note"><Icon name="leaf" :size="25"/><p>每一件旧物，<br>都有再次发光的机会。</p></div></aside><section class="market-results"><div class="results-heading"><p>共 <strong>{{filtered.length}}</strong> 件好物，正在等待新归宿<span v-if="q"> · “{{q}}”</span></p><select v-model="sort" aria-label="商品排序"><option value="new">最新发布</option><option value="price-up">价格从低到高</option><option value="price-down">价格从高到低</option></select></div><div class="product-grid market-grid"><ProductCard v-for="product in shown" :key="product.id" :product="product"/></div><div v-if="!shown.length" class="empty-state panel"><Icon name="search" :size="44"/><h2>还没有找到这一份心动</h2><p>试试别的关键词，或放宽一点筛选条件。</p><button class="button outline" @click="reset">看看所有闲置</button></div><div v-if="pages>1" class="pagination"><button class="icon-button" :disabled="page===1" @click="page--" aria-label="上一页">←</button><button v-for="n in pages" :key="n" :class="{active:n===page}" @click="page=n">{{n}}</button><button class="icon-button" :disabled="page===pages" @click="page++" aria-label="下一页">→</button></div></section></div></div></template>
